  position: absolute;
  left: 0; bottom: 0;
  width: 100%; height: 2px;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,.9) 50%, transparent);
  animation: sds-edgeScanKf 3s ease-in-out infinite 1.5s;
}

