    transform: translateX(6px) rotate(3deg);
  }
  45% {
    transform: translateX(-5px) rotate(-2deg);
  }
  60% {
    transform: translateX(4px) rotate(1.5deg);
  }
  75% {
    transform: translateX(-2px) rotate(-0.8deg);
  }
  90% {
    transform: translateX(1px) rotate(0.4deg);
  }
}

