    filter: blur(22px);
    transform: scale(1.12);
  }
  55% {
    opacity: 1;
    filter: blur(3px);
    transform: scale(1.02);
  }
  100% {
    opacity: 1;
    filter: blur(0);
    transform: scale(1);
  }
}

